const corpo = $json.body || $json;
const documento = corpo.document || corpo.data || corpo;
const dealId = String(documento.id || documento._id || corpo.id || '');
if (!/^[0-9a-f]{24}$/.test(dealId)) return { json: { ignorar: true, motivo: 'deal_id_invalido' } };
return { json: { ignorar: false, dealId } };

const negociacao = $('Buscar negociação no RD').first().json;
const preparo = $json;
const CAMPO_LEAD_ID = '6afe21ef2fbf58001fcfc746';
const FONTE_DIGITAL = '6afe1e7f7d2654001dbc1dc1';
const ETAPAS_QUE_VIRAM_EVENTO = { 'Novo lead': 'Novo lead', 'Definição do produto': 'Definição do produto', 'Análise de crédito': 'Análise de crédito', 'Condições comerciais': 'Condições comerciais', 'Coleta de dados': 'Coleta de dados', 'Proposta no banco': 'Proposta no banco', 'Aprovado': 'Aprovado' };
const campos = negociacao.deal_custom_fields || [];
const campoLead = campos.find((c) => c.custom_field_id === CAMPO_LEAD_ID || (c.custom_field || {})._id === CAMPO_LEAD_ID || (c.custom_field || {}).id === CAMPO_LEAD_ID);
const leadId = campoLead && campoLead.value ? String(campoLead.value) : '';
const fonte = String((negociacao.deal_source || {}).id || (negociacao.deal_source || {})._id || negociacao.deal_source_id || '');
const canal = leadId ? 'formulario' : fonte === FONTE_DIGITAL ? 'whatsapp' : 'fora_de_anuncio';
if (canal === 'fora_de_anuncio') return { json: { enviar: false, motivo: 'fonte_fora_de_anuncio' } };
if (canal === 'whatsapp' && !preparo.telefone) return { json: { enviar: false, motivo: 'whatsapp_sem_telefone' } };
const ganha = negociacao.win === true;
const etapa = (negociacao.deal_stage || {}).name || '';
const nomeDoEvento = ganha ? 'Purchase' : ETAPAS_QUE_VIRAM_EVENTO[etapa];
if (!nomeDoEvento) return { json: { enviar: false, motivo: 'etapa_sem_evento' } };
const dealId = preparo.dealId;
const chave = `${dealId}:${nomeDoEvento}`;
const memoria = $getWorkflowStaticData('global');
memoria.enviados = memoria.enviados || {};
if (memoria.enviados[chave]) return { json: { enviar: false, motivo: 'ja_enviado', chave } };
const quando = ganha && negociacao.closed_at ? new Date(negociacao.closed_at) : new Date();
const userData = { external_id: [preparo.externo] };
if (preparo.telefone) userData.ph = [preparo.ph];
if (leadId) userData.lead_id = Number(leadId);
const evento = {
  event_name: nomeDoEvento,
  event_time: Math.floor(quando.getTime() / 1000),
  event_id: `rdcrm_${chave}`,
  action_source: canal === 'formulario' ? 'system_generated' : 'chat',
  user_data: userData,
  custom_data: canal === 'formulario' ? { event_source: 'crm', lead_event_source: 'RD Station CRM' } : { lead_event_source: 'RD Station CRM' }
};
if (ganha) {
  evento.custom_data.currency = 'BRL';
  evento.custom_data.value = Number(negociacao.amount_total) || 0;
}
const body = { data: [evento] };
if (/^teste/i.test(String(negociacao.name || ''))) body.test_event_code = 'TEST24CAPI';
return { json: { enviar: true, chave, canal, body } };

const chave = $('Montar evento da Meta').item.json.chave;
const memoria = $getWorkflowStaticData('global');
memoria.enviados = memoria.enviados || {};
memoria.enviados[chave] = new Date().toISOString();
return { json: { chave, eventos_recebidos: $json.events_received, fbtrace_id: $json.fbtrace_id } };

const negociacao = $('Buscar negociação no RD').first().json;
const contatos = ($input.first().json.contacts || []);
const telefoneBruto = String((((contatos[0] || {}).phones || [])[0] || {}).phone || '');
const digitos = telefoneBruto.replace(/\D/g, '');
const telefone = digitos.length === 10 || digitos.length === 11 ? `55${digitos}` : (digitos.length === 12 || digitos.length === 13) && digitos.startsWith('55') ? digitos : '';
return [{ json: { dealId: String(negociacao.id || negociacao._id || ''), telefone } }];
